#include <format>
#include <iostream>

int main() {
  int a = 1;
  int b = 2;
  int& r = a;  // r is another name for a, for the rest of its life
  r = b;       // copies the value of b into a; r still refers to a
  int* p = &a;
  p = &b;      // p now points at b
  *p = 20;
  std::cout << std::format("a={} b={} r={} *p={}\n", a, b, r, *p);
}

#include <algorithm>
