#include <vector>

struct Waypoint {
  std::string name;
  double x = 0;
  double y = 0;
};

class Route {
 public:
  void add(Waypoint w) { points_.push_back(std::move(w)); }  // kept, so taken by value and moved

  [[nodiscard]] double length() const {
    if (points_.size() < 2) return 0.0;
    // Adds up the distance from each waypoint to the next one.
    return std::transform_reduce(points_.begin(), points_.end() - 1, points_.begin() + 1, 0.0, std::plus<>{},
                                 [](const Waypoint& from, const Waypoint& to) {
                                   return std::hypot(to.x - from.x, to.y - from.y);
                                 });
  }

  [[nodiscard]] const Waypoint* find(std::string_view name) const {  // nullptr means "not found"
    const auto it = std::ranges::find(points_, name, &Waypoint::name);
    return it != points_.end() ? &*it : nullptr;
  }

  [[nodiscard]] const Waypoint& at(std::ptrdiff_t i) const { return points_.at(static_cast<std::size_t>(i)); }
  [[nodiscard]] Waypoint& at(std::ptrdiff_t i) { return points_.at(static_cast<std::size_t>(i)); }

 private:
  std::vector<Waypoint> points_;
};

int main() {
  Route route;
  route.add({.name = "dock", .x = 0, .y = 0});
  route.add({.name = "shelf", .x = 3, .y = 4});
  route.add({.name = "gate", .x = 3, .y = 10});
  std::cout << std::format("length {:.1f}\n", route.length());

  route.at(2).name = "exit";
  const Route& reader = route;
  for (const std::string_view name : {"exit", "gate"}) {
    if (const Waypoint* hit = reader.find(name)) {
      std::cout << std::format("{} is at ({}, {})\n", name, hit->x, hit->y);
    } else {
      std::cout << std::format("{} not found\n", name);
    }
  }
}

