[[nodiscard]] std::vector<std::string_view> split(std::string_view text, char sep) {
  std::vector<std::string_view> parts;
  for (const auto piece : std::views::split(text, sep)) parts.emplace_back(piece.begin(), piece.end());
  return parts;
}

[[nodiscard]] std::optional<double> average(std::span<const double> values) {
  if (values.empty()) return std::nullopt;
  return std::accumulate(values.begin(), values.end(), 0.0) / static_cast<double>(values.size());
}

int main() {
  for (const std::string_view part : split("a,b,,c", ',')) std::cout << std::format("[{}]", part);
  std::cout << '\n';

  const std::vector<double> speeds{0.5, 1.0, 1.5};
  const std::array<double, 3> gains{1.0, 2.0, 6.0};
  const auto show = [](std::optional<double> avg) { return avg ? std::format("{:.2f}", *avg) : std::string("none"); };
  std::cout << std::format("{} {} {}\n", show(average(speeds)), show(average(gains)), show(average({})));
}

