#include <format>
#include <functional>
#include <iostream>

[[nodiscard]] std::function<int()> make_counter() {
  int count = 0;
  return [&count] { return ++count; };  // borrows a local that dies on return
}

int main() {
  const std::function<int()> next = make_counter();
  std::cout << std::format("{}\n", next());
}
